63	            DYNAMIC_SECURITY_CONFIGS,
64	            DynamicListenerConfig.RECONFIGURABLE_CONFIGS)
65	        .flatMap(Collection::stream)
66	        .filter(c -> !CLUSTER_LEVEL_LISTENER_CONFIGS.contains(c))
67	        .collect(Collectors.toUnmodifiableSet());
68	
69	    public static final Set<String> ALL_DYNAMIC_CONFIGS = Stream.of(
70	            DYNAMIC_SECURITY_CONFIGS,
71	            LogCleaner.RECONFIGURABLE_CONFIGS,
72	            DynamicLogConfig.RECONFIGURABLE_CONFIGS,
73	            DynamicThreadPool.RECONFIGURABLE_CONFIGS,
74	            List.of(MetricConfigs.METRIC_REPORTER_CLASSES_CONFIG),
75	            DynamicListenerConfig.RECONFIGURABLE_CONFIGS,
76	            SocketServer.RECONFIGURABLE_CONFIGS,
77	            DYNAMIC_PRODUCER_STATE_MANAGER_CONFIGS,
78	            DynamicRemoteLogConfig.RECONFIGURABLE_CONFIGS,
79	            DynamicReplicationConfig.RECONFIGURABLE_CONFIGS,
80	            List.of(AbstractConfig.CONFIG_PROVIDERS_CONFIG),
81	            GroupCoordinatorConfig.RECONFIGURABLE_CONFIGS,
82	            DynamicQuotaConfig.RECONFIGURABLE_CONFIGS,
83	            ShareCoordinatorConfig.RECONFIGURABLE_CONFIGS)
84	        .flatMap(Collection::stream)
85	        .collect(Collectors.toUnmodifiableSet());
