87	    private static final Set<String> LISTENER_MECHANISM_CONFIGS = Set.of(
88	            SaslConfigs.SASL_JAAS_CONFIG,
89	            SaslConfigs.SASL_LOGIN_CALLBACK_HANDLER_CLASS,
90	            SaslConfigs.SASL_LOGIN_CLASS,
91	            BrokerSecurityConfigs.SASL_SERVER_CALLBACK_HANDLER_CLASS_CONFIG,
92	            BrokerSecurityConfigs.CONNECTIONS_MAX_REAUTH_MS_CONFIG);
