94	    private static final Pattern LISTENER_CONFIG_REGEX = Pattern.compile("listener\\.name\\.[^.]*\\.(.*)");
95	
96	    public static List<String> brokerConfigSynonyms(String name, boolean matchListenerOverride) {
97	        List<String> logRollConfigs = List.of(ServerLogConfigs.LOG_ROLL_TIME_MILLIS_CONFIG, ServerLogConfigs.LOG_ROLL_TIME_HOURS_CONFIG);
98	        List<String> logRollJitterConfigs = List.of(ServerLogConfigs.LOG_ROLL_TIME_JITTER_MILLIS_CONFIG, ServerLogConfigs.LOG_ROLL_TIME_JITTER_HOURS_CONFIG);
99	        List<String> logRetentionConfigs = List.of(ServerLogConfigs.LOG_RETENTION_TIME_MILLIS_CONFIG, ServerLogConfigs.LOG_RETENTION_TIME_MINUTES_CONFIG, ServerLogConfigs.LOG_RETENTION_TIME_HOURS_CONFIG);
100	        List<String> logFlushConfigs = List.of(ServerLogConfigs.LOG_FLUSH_INTERVAL_MS_CONFIG, ServerLogConfigs.LOG_FLUSH_SCHEDULER_INTERVAL_MS_CONFIG);
101	        if (logRollConfigs.contains(name)) {
102	            return logRollConfigs;
103	        } else if (logRollJitterConfigs.contains(name)) {
104	            return logRollJitterConfigs;
105	        } else if (ServerLogConfigs.LOG_FLUSH_INTERVAL_MS_CONFIG.equals(name)) { // KafkaLogConfigs.LOG_FLUSH_SCHEDULER_INTERVAL_MS_CONFIG is used as default
106	            return logFlushConfigs;
107	        } else if (logRetentionConfigs.contains(name)) {
108	            return logRetentionConfigs;
109	        } else if (matchListenerOverride) {
110	            Matcher matcher = LISTENER_CONFIG_REGEX.matcher(name);
111	            if (matcher.matches()) {
112	                String baseName = matcher.group(1);
113	                // `ListenerMechanismConfigs` are specified as listenerPrefix.mechanism.<configName>
114	                // and other listener configs are specified as listenerPrefix.<configName>
115	                // Add <configName> as a synonym in both cases.
116	                Optional<String> mechanismConfig = LISTENER_MECHANISM_CONFIGS.stream().filter(baseName::endsWith).findFirst();
117	                return List.of(name, mechanismConfig.orElse(baseName));
118	            }
119	        }
120	        return List.of(name);
121	    }
