148	            if (matcher.matches()) {
149	                String baseName = matcher.group(1);
150	                baseProps.put(baseName, value);
151	            } else {
152	                baseProps.put(name, value);
153	            }
154	        });
155	        DynamicConfig.Broker.validate(baseProps);
