437	      currentConfig = newConfig
438	      kafkaConfig.updateCurrentConfig(newConfig)
439	
440	      // Process BrokerReconfigurable updates after current config is updated
441	      brokerReconfigurablesToUpdate.foreach(_.reconfigure(oldConfig, newConfig))
