445	  private def processReconfiguration(newProps: Map[String, String], validateOnly: Boolean, doLog: Boolean = false): (KafkaConfig, List[BrokerReconfigurable]) = {
446	    val newConfig = new KafkaConfig(newProps.asJava, doLog)
447	    val (changeMap, deletedKeySet) = updatedConfigs(newConfig.originalsFromThisConfig, currentConfig.originals)
448	    if (changeMap.nonEmpty || deletedKeySet.nonEmpty) {
449	      try {
450	        val customConfigs = new util.HashMap[String, Object](newConfig.originalsFromThisConfig) // non-Kafka configs
451	        newConfig.valuesFromThisConfig.keySet.forEach(k => customConfigs.remove(k))
452	        reconfigurables.forEach {
453	          case listenerReconfigurable: ListenerReconfigurable =>
454	            processListenerReconfigurable(listenerReconfigurable, newConfig, customConfigs, validateOnly, reloadOnly = false)
455	          case reconfigurable =>
456	            if (needsReconfiguration(reconfigurable.reconfigurableConfigs, changeMap.keySet, deletedKeySet))
457	              processReconfigurable(reconfigurable, changeMap.keySet, newConfig.valuesFromThisConfig, customConfigs, validateOnly)
458	        }
459	
460	        // BrokerReconfigurable updates are processed after config is updated. Only do the validation here.
461	        val brokerReconfigurablesToUpdate = mutable.Buffer[BrokerReconfigurable]()
462	        brokerReconfigurables.forEach { reconfigurable =>
463	          if (needsReconfiguration(reconfigurable.reconfigurableConfigs, changeMap.keySet, deletedKeySet)) {
464	            reconfigurable.validateReconfiguration(newConfig)
465	            if (!validateOnly)
466	              brokerReconfigurablesToUpdate += reconfigurable
467	          }
468	        }
469	        (newConfig, brokerReconfigurablesToUpdate.toList)
470	      } catch {
471	        case e: Exception =>
472	          if (!validateOnly)
473	            error(s"Failed to update broker configuration with configs : " +
474	                  s"${ConfigUtils.configMapToRedactedString(newConfig.originalsFromThisConfig, KafkaConfig.configDef)}", e)
475	          throw new ConfigException("Invalid dynamic configuration", e)
476	      }
477	    }
478	    else
479	      (currentConfig, List.empty)
480	  }
