482	  private def needsReconfiguration(reconfigurableConfigs: util.Set[String], updatedKeys: Set[String], deletedKeys: Set[String]): Boolean = {
483	    reconfigurableConfigs.asScala.intersect(updatedKeys).nonEmpty ||
484	      reconfigurableConfigs.asScala.intersect(deletedKeys).nonEmpty
485	  }
