487	  private def processListenerReconfigurable(listenerReconfigurable: ListenerReconfigurable,
488	                                            newConfig: KafkaConfig,
489	                                            customConfigs: util.Map[String, Object],
490	                                            validateOnly: Boolean,
491	                                            reloadOnly:  Boolean): Unit = {
492	    val listenerName = listenerReconfigurable.listenerName
493	    val oldValues = currentConfig.valuesWithPrefixOverride(listenerName.configPrefix)
494	    val newValues = newConfig.valuesFromThisConfigWithPrefixOverride(listenerName.configPrefix)
495	    val (changeMap, deletedKeys) = updatedConfigs(newValues, oldValues)
496	    val updatedKeys = changeMap.keySet
497	    val configsChanged = needsReconfiguration(listenerReconfigurable.reconfigurableConfigs, updatedKeys, deletedKeys)
498	    // if `reloadOnly`, reconfigure if configs haven't changed. Otherwise reconfigure if configs have changed
499	    if (reloadOnly != configsChanged)
500	      processReconfigurable(listenerReconfigurable, updatedKeys, newValues, customConfigs, validateOnly)
501	  }
