503	  private def processReconfigurable(reconfigurable: Reconfigurable,
504	                                    updatedConfigNames: Set[String],
505	                                    allNewConfigs: util.Map[String, _],
506	                                    newCustomConfigs: util.Map[String, Object],
507	                                    validateOnly: Boolean): Unit = {
508	    val newConfigs = new util.HashMap[String, Object]
509	    allNewConfigs.forEach((k, v) => newConfigs.put(k, v.asInstanceOf[AnyRef]))
510	    newConfigs.putAll(newCustomConfigs)
511	    try {
512	      reconfigurable.validateReconfiguration(newConfigs)
513	    } catch {
514	      case e: ConfigException => throw e
515	      case _: Exception =>
516	        throw new ConfigException(s"Validation of dynamic config update of $updatedConfigNames failed with class ${reconfigurable.getClass}")
517	    }
518	
519	    if (!validateOnly) {
520	      info(s"Reconfiguring $reconfigurable, updated configs: $updatedConfigNames " +
521	           s"custom configs: ${ConfigUtils.configMapToRedactedString(newCustomConfigs, KafkaConfig.configDef)}")
522	      reconfigurable.reconfigure(newConfigs)
523	    }
524	  }
