28	/**
29	 * A description of a log directory on a particular broker.
30	 */
31	public class LogDirDescription {
32	    private final Map<TopicPartition, ReplicaInfo> replicaInfos;
33	    private final ApiException error;
34	    private final OptionalLong totalBytes;
35	    private final OptionalLong usableBytes;
