38	        this(error, replicaInfos, UNKNOWN_VOLUME_BYTES, UNKNOWN_VOLUME_BYTES);
39	    }
40	
41	    public LogDirDescription(ApiException error, Map<TopicPartition, ReplicaInfo> replicaInfos, long totalBytes, long usableBytes) {
42	        this.error = error;
43	        this.replicaInfos = replicaInfos;
44	        this.totalBytes = (totalBytes == UNKNOWN_VOLUME_BYTES) ? OptionalLong.empty() : OptionalLong.of(totalBytes);
45	        this.usableBytes = (usableBytes == UNKNOWN_VOLUME_BYTES) ? OptionalLong.empty() : OptionalLong.of(usableBytes);
46	    }
47	
48	    /**
49	     * Returns `ApiException` if the log directory is offline or an error occurred, otherwise returns null.
50	     * <ul>
51	     * <li> KafkaStorageException - The log directory is offline.
52	     * <li> UnknownServerException - The server experienced an unexpected error when processing the request.
53	     * </ul>
54	     */
55	    public ApiException error() {
56	        return error;
57	    }
58	
59	    /**
60	     * A map from topic partition to replica information for that partition
61	     * in this log directory.
62	     */
63	    public Map<TopicPartition, ReplicaInfo> replicaInfos() {
64	        return unmodifiableMap(replicaInfos);
65	    }
66	
67	    /**
68	     * The total size of the volume this log directory is on or empty if the broker did not return a value.
69	     * For volumes larger than Long.MAX_VALUE, Long.MAX_VALUE is returned.
70	     * This value does not include the size of data stored in remote storage.
71	     */
72	    public OptionalLong totalBytes() {
73	        return totalBytes;
74	    }
75	
76	    /**
77	     * The usable size on the volume this log directory is on or empty if the broker did not return a value.
78	     * For usable sizes larger than Long.MAX_VALUE, Long.MAX_VALUE is returned.
79	     * This value does not include the size of data stored in remote storage.
80	     */
81	    public OptionalLong usableBytes() {
82	        return usableBytes;
83	    }
84	
