438	        BrokerRegistrationRequestData.FeatureCollection features = new BrokerRegistrationRequestData.FeatureCollection();
439	        supportedFeatures.forEach((name, range) ->
440	                features.add(new BrokerRegistrationRequestData.Feature()
441	                        .setName(name)
