452	            .setIncarnationId(incarnationId)
453	            .setListeners(advertisedListeners)
454	            .setRack(rack.orElse(null))
455	            .setPreviousBrokerEpoch(previousBrokerEpoch.orElse(-1L))
456	            .setLogDirs(sortedLogDirs);
