1974	            throw new InvalidReplicaAssignmentException("The manual partition " +
1975	                "assignment includes an empty replica list.");
1976	        }
1977	        List<Integer> sortedBrokerIds = new ArrayList<>(assignment.replicas());
1978	        sortedBrokerIds.sort(Integer::compare);
1979	        Integer prevBrokerId = null;
1980	        for (Integer brokerId : sortedBrokerIds) {
1981	            if (!clusterControl.brokerRegistrations().containsKey(brokerId)) {
1982	                throw new InvalidReplicaAssignmentException("The manual partition " +
1983	                    "assignment includes broker " + brokerId + ", but no such broker is " +
1984	                    "registered.");
1985	            }
1986	            if (brokerId.equals(prevBrokerId)) {
1987	                throw new InvalidReplicaAssignmentException("The manual partition " +
1988	                    "assignment includes the broker " + prevBrokerId + " more than " +
1989	                    "once.");
1990	            }
1991	            prevBrokerId = brokerId;
1992	        }
1993	        if (replicationFactor.isPresent() &&
1994	                sortedBrokerIds.size() != replicationFactor.getAsInt()) {
1995	            throw new InvalidReplicaAssignmentException("The manual partition " +
1996	                "assignment includes a partition with " + sortedBrokerIds.size() +
1997	                " replica(s), but this is not consistent with previous " +
1998	                "partitions, which have " + replicationFactor.getAsInt() + " replica(s).");
1999	        }
