2240	
2241	        List<Integer> currentReplicas = Replicas.toList(part.replicas);
2242	        PartitionReassignmentReplicas reassignment =
2243	            new PartitionReassignmentReplicas(currentAssignment, targetAssignment);
2244	        PartitionChangeBuilder builder = new PartitionChangeBuilder(
