    @ClusterTest(serverProperties = {
        @ClusterConfigProperty(id = 1, key = ServerLogConfigs.CORDONED_LOG_DIRS_CONFIG, value = ServerLogConfigs.CORDONED_LOG_DIRS_ALL)
    })
