251	            );
252	            this.clusterControl = new ClusterControlManager.Builder().
253	                setLogContext(logContext).
254	                setTime(time).
255	                setSnapshotRegistry(snapshotRegistry).
256	                setSessionTimeoutNs(TimeUnit.MILLISECONDS.convert(BROKER_SESSION_TIMEOUT_MS, TimeUnit.NANOSECONDS)).
257	                setReplicaPlacer(new StripedReplicaPlacer(random)).
258	                setFeatureControlManager(featureControl).
259	                setBrokerShutdownHandler(this::handleBrokerShutdown).
260	                build();
261	            this.configurationControl = new ConfigurationControlManager.Builder().
262	                setSnapshotRegistry(snapshotRegistry).
263	                setFeatureControl(featureControl).
264	                setStaticConfig(staticConfig).
265	                setKafkaConfigSchema(FakeKafkaConfigSchema.INSTANCE).
266	                build();
267	            this.offsetControlManager = new OffsetControlManager.Builder().
268	                setSnapshotRegistry(snapshotRegistry).
269	                build();
