272	                setLogContext(logContext).
273	                setMaxElectionsPerImbalance(Integer.MAX_VALUE).
274	                setConfigurationControl(configurationControl).
275	                setClusterControl(clusterControl).
276	                setCreateTopicPolicy(createTopicPolicy).
277	                setFeatureControl(featureControl).
278	                build();
279	            clusterControl.activate();
280	        }
