381	        void registerBrokers(Integer... brokerIds) {
382	            Object[] brokersAndDirs = new Object[brokerIds.length * 2];
383	            for (int i = 0; i < brokerIds.length; i++) {
384	                brokersAndDirs[i * 2] = brokerIds[i];
385	                brokersAndDirs[i * 2 + 1] = List.of(
386	                    Uuid.fromString("TESTBROKER" + Integer.toString(100000 + brokerIds[i]).substring(1) + "DIRAAAA")
387	                );
