            replay(result.records());
            return result;
        }

        Set<Integer> fencedBrokerIds() {
            return clusterControl.brokerRegistrations().values()
                    .stream()
                    .filter(BrokerRegistration::fenced)
                    .map(BrokerRegistration::id)
                    .collect(Collectors.toSet());
