    ctx.unfenceBrokers(0, 1, 2);
    Uuid fooId = ctx.createTestTopic("foo", new int[][] {new int[] {0, 1, 2}}).topicId();
    ctx.createPartitions(2, "foo", new int[][] {new int[] {3, 4, 5}},
