import org.apache.kafka.common.message.AlterPartitionReassignmentsRequestData;
import org.apache.kafka.common.message.AlterPartitionReassignmentsRequestData.ReassignablePartition;
import org.apache.kafka.common.message.AlterPartitionReassignmentsRequestData.ReassignableTopic;
import org.apache.kafka.common.message.AlterPartitionReassignmentsResponseData;
import org.apache.kafka.common.message.BrokerHeartbeatRequestData;
import org.apache.kafka.common.message.CreatePartitionsRequestData.CreatePartitionsAssignment;
import org.apache.kafka.common.message.CreatePartitionsRequestData.CreatePartitionsTopic;
import org.apache.kafka.common.message.CreatePartitionsResponseData.CreatePartitionsTopicResult;
import org.apache.kafka.common.message.CreateTopicsRequestData;
import org.apache.kafka.common.message.CreateTopicsRequestData.CreatableReplicaAssignment;
import org.apache.kafka.common.message.CreateTopicsRequestData.CreatableTopic;
import org.apache.kafka.common.message.CreateTopicsResponseData;
import org.apache.kafka.common.message.CreateTopicsResponseData.CreatableTopicResult;
import org.apache.kafka.common.message.RequestHeaderData;
import org.apache.kafka.common.metadata.FeatureLevelRecord;
import org.apache.kafka.common.metadata.RegisterBrokerRecord;
import org.apache.kafka.common.protocol.ApiKeys;
import org.apache.kafka.common.protocol.ApiMessage;
import org.apache.kafka.common.security.auth.KafkaPrincipal;
import org.apache.kafka.common.security.auth.SecurityProtocol;
import org.apache.kafka.common.utils.LogContext;
import org.apache.kafka.common.utils.MockTime;
import org.apache.kafka.metadata.BrokerHeartbeatReply;
import org.apache.kafka.metadata.KafkaConfigSchema;
import org.apache.kafka.metadata.Replicas;
import org.apache.kafka.metadata.placement.StripedReplicaPlacer;
import org.apache.kafka.server.common.ApiMessageAndVersion;
import org.apache.kafka.server.common.EligibleLeaderReplicasVersion;
import org.apache.kafka.server.common.MetadataVersion;
import org.apache.kafka.server.config.ConfigSynonym;
import org.apache.kafka.server.util.MockRandom;
import org.apache.kafka.timeline.SnapshotRegistry;

import org.junit.jupiter.api.Test;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;
import java.util.Set;
import java.util.concurrent.TimeUnit;

import static org.apache.kafka.common.protocol.Errors.INELIGIBLE_REPLICA;
import static org.apache.kafka.common.protocol.Errors.INVALID_REPLICATION_FACTOR;
import static org.apache.kafka.common.protocol.Errors.INVALID_REPLICA_ASSIGNMENT;
import static org.apache.kafka.common.protocol.Errors.NONE;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

public class aih_probe3 {
    private static final int BROKER_SESSION_TIMEOUT_MS = 1000;

    static final KafkaConfigSchema SCHEMA;
    static {
        Map<ConfigResource.Type, ConfigDef> configs = new HashMap<>();
        configs.put(ConfigResource.Type.BROKER, new ConfigDef().
            define("unclean.leader.election.enable", ConfigDef.Type.BOOLEAN, "false", ConfigDef.Importance.HIGH, "").
            define("min.insync.replicas", ConfigDef.Type.INT, "1", ConfigDef.Importance.HIGH, ""));
        configs.put(ConfigResource.Type.TOPIC, new ConfigDef().
            define("unclean.leader.election.enable", ConfigDef.Type.BOOLEAN, "false", ConfigDef.Importance.HIGH, "").
            define("min.insync.replicas", ConfigDef.Type.INT, "1", ConfigDef.Importance.HIGH, ""));
        Map<String, List<ConfigSynonym>> synonyms = new HashMap<>();
        synonyms.put("unclean.leader.election.enable", List.of(new ConfigSynonym("unclean.leader.election.enable")));
        synonyms.put("min.insync.replicas", List.of(new ConfigSynonym("min.insync.replicas")));
        SCHEMA = new KafkaConfigSchema(configs, synonyms);
    }

    private static ControllerRequestContext anonymousContextFor(ApiKeys apiKeys) {
        return new ControllerRequestContext(
            new RequestHeaderData()
                .setRequestApiKey(apiKeys.id)
                .setRequestApiVersion(apiKeys.latestVersion()),
            KafkaPrincipal.ANONYMOUS,
            OptionalLong.empty(),
            __ -> { }
        );
    }

    private static class ReplicationControlTestContext {
        final SnapshotRegistry snapshotRegistry = new SnapshotRegistry(new LogContext());
        final LogContext logContext = new LogContext();
        final MockTime time = new MockTime();
        final MockRandom random = new MockRandom();
        final FeatureControlManager featureControl;
        final ClusterControlManager clusterControl;
        final ConfigurationControlManager configurationControl;
        final ReplicationControlManager replicationControl;

        void replay(List<ApiMessageAndVersion> records) {
            replayAll(clusterControl, records);
            replayAll(configurationControl, records);
            replayAll(replicationControl, records);
        }

        static void replayAll(Object target, List<ApiMessageAndVersion> recordsAndVersions) {
            for (ApiMessageAndVersion recordAndVersion : recordsAndVersions) {
                ApiMessage record = recordAndVersion.message();
                try {
                    try {
                        Method method = target.getClass().getMethod("replay", record.getClass());
                        method.invoke(target, record);
                    } catch (NoSuchMethodException e) {
                        try {
                            Method method = target.getClass().getMethod("replay", record.getClass(), long.class);
                            method.invoke(target, record, 0L);
                        } catch (NoSuchMethodException i) {
                            // ignore
                        }
                    }
                } catch (InvocationTargetException e) {
                    throw new RuntimeException(e.getCause());
                } catch (IllegalAccessException e) {
                    throw new RuntimeException(e);
                }
            }
        }

        ReplicationControlTestContext() {
            this.featureControl = new FeatureControlManager.Builder().
                setSnapshotRegistry(snapshotRegistry).
                setQuorumFeatures(new QuorumFeatures(0,
                    QuorumFeatures.defaultSupportedFeatureMap(true),
                    List.of(0))).
                build();
            this.featureControl.replay(new FeatureLevelRecord().
                setName(MetadataVersion.FEATURE_NAME).
                setFeatureLevel(MetadataVersion.latestTesting().featureLevel()));
            featureControl.replay(new FeatureLevelRecord()
                .setName(EligibleLeaderReplicasVersion.FEATURE_NAME)
                    .setFeatureLevel(EligibleLeaderReplicasVersion.ELRV_0.featureLevel()));
            this.clusterControl = new ClusterControlManager.Builder().
                setLogContext(logContext).
                setTime(time).
                setSnapshotRegistry(snapshotRegistry).
                setSessionTimeoutNs(TimeUnit.MILLISECONDS.convert(BROKER_SESSION_TIMEOUT_MS, TimeUnit.NANOSECONDS)).
                setReplicaPlacer(new StripedReplicaPlacer(random)).
                setFeatureControlManager(featureControl).
                setBrokerShutdownHandler(this::handleBrokerShutdown).
                build();
            this.configurationControl = new ConfigurationControlManager.Builder().
                setSnapshotRegistry(snapshotRegistry).
                setFeatureControl(featureControl).
                setKafkaConfigSchema(SCHEMA).
                build();
            this.replicationControl = new ReplicationControlManager.Builder().
                setSnapshotRegistry(snapshotRegistry).
                setLogContext(logContext).
                setMaxElectionsPerImbalance(Integer.MAX_VALUE).
                setConfigurationControl(configurationControl).
                setClusterControl(clusterControl).
                setFeatureControl(featureControl).
                build();
            clusterControl.activate();
        }

        void handleBrokerShutdown(int brokerId, boolean isCleanShutdown, List<ApiMessageAndVersion> records) {
            replicationControl.handleBrokerShutdown(brokerId, isCleanShutdown, records);
        }

        CreatableTopicResult createTestTopic(String name,
                                             int numPartitions,
                                             short replicationFactor,
                                             short expectedErrorCode) {
            CreateTopicsRequestData request = new CreateTopicsRequestData();
            CreatableTopic topic = new CreatableTopic().setName(name);
            topic.setNumPartitions(numPartitions).setReplicationFactor(replicationFactor);
            request.topics().add(topic);
            ControllerRequestContext requestContext = anonymousContextFor(ApiKeys.CREATE_TOPICS);
            ControllerResult<CreateTopicsResponseData> result =
                replicationControl.createTopics(requestContext, request, Set.of(name));
            CreatableTopicResult topicResult = result.response().topics().find(name);
            assertNotNull(topicResult);
            assertEquals(expectedErrorCode, topicResult.errorCode(), topicResult.errorMessage());
            if (expectedErrorCode == NONE.code()) {
                replay(result.records());
            }
            return topicResult;
        }

        CreatableTopicResult createTestTopic(String name, int[][] replicas) {
            return createTestTopic(name, replicas, (short) 0);
        }

        CreatableTopicResult createTestTopic(String name, int[][] replicas,
                                             short expectedErrorCode) {
            assertNotEquals(0, replicas.length);
            CreateTopicsRequestData request = new CreateTopicsRequestData();
            CreatableTopic topic = new CreatableTopic().setName(name);
            topic.setNumPartitions(-1).setReplicationFactor((short) -1);
            for (int i = 0; i < replicas.length; i++) {
                topic.assignments().add(new CreatableReplicaAssignment().
                    setPartitionIndex(i).setBrokerIds(Replicas.toList(replicas[i])));
            }
            request.topics().add(topic);
            ControllerRequestContext requestContext = anonymousContextFor(ApiKeys.CREATE_TOPICS);
            ControllerResult<CreateTopicsResponseData> result =
                replicationControl.createTopics(requestContext, request, Set.of(name));
            CreatableTopicResult topicResult = result.response().topics().find(name);
            assertNotNull(topicResult);
            assertEquals(expectedErrorCode, topicResult.errorCode(), topicResult.errorMessage());
            if (expectedErrorCode == NONE.code()) {
                replay(result.records());
            }
            return topicResult;
        }

        void createPartitions(int count, String name, int[][] replicas, short expectedErrorCode) {
            CreatePartitionsTopic topic = new CreatePartitionsTopic().
                setName(name).
                setCount(count);
            for (int[] replica : replicas) {
                topic.assignments().add(new CreatePartitionsAssignment().
                    setBrokerIds(Replicas.toList(replica)));
            }
            ControllerRequestContext requestContext = anonymousContextFor(ApiKeys.CREATE_PARTITIONS);
            ControllerResult<List<CreatePartitionsTopicResult>> result =
                replicationControl.createPartitions(requestContext, List.of(topic));
            CreatePartitionsTopicResult topicResult = result.response().get(0);
            assertEquals(expectedErrorCode, topicResult.errorCode(), topicResult.errorMessage());
            replay(result.records());
        }

        @SuppressWarnings("unchecked")
        void registerBrokersWithDirs(Object... brokerIdsAndDirs) {
            for (int i = 0; i < brokerIdsAndDirs.length / 2; i++) {
                int brokerId = (int) brokerIdsAndDirs[i * 2];
                List<Uuid> logDirs = (List<Uuid>) brokerIdsAndDirs[i * 2 + 1];
                RegisterBrokerRecord brokerRecord = new RegisterBrokerRecord().
                    setBrokerEpoch(defaultBrokerEpoch(brokerId)).setBrokerId(brokerId).
                        setRack(null).setLogDirs(logDirs);
                brokerRecord.endPoints().add(new RegisterBrokerRecord.BrokerEndpoint().
                    setSecurityProtocol(SecurityProtocol.PLAINTEXT.id).
                    setPort((short) 9092 + brokerId).
                    setName("PLAINTEXT").
                    setHost("localhost"));
                replay(List.of(new ApiMessageAndVersion(brokerRecord, (short) 3)));
            }
        }

        void unfenceBrokers(Integer... brokerIds) {
            for (int brokerId : brokerIds) {
                clusterControl.trackBrokerHeartbeat(brokerId, defaultBrokerEpoch(brokerId));
                ControllerResult<BrokerHeartbeatReply> result = replicationControl.
                    processBrokerHeartbeat(new BrokerHeartbeatRequestData().
                        setBrokerId(brokerId).setBrokerEpoch(defaultBrokerEpoch(brokerId)).
                        setCurrentMetadataOffset(1).
                        setWantFence(false).setWantShutDown(false), 0);
                replay(result.records());
            }
        }
    }

    private static Long defaultBrokerEpoch(int brokerId) {
        return brokerId + 100L;
    }

    private static List<ApiMessageAndVersion> heartbeatWithCordonedDirs(
        ReplicationControlTestContext ctx,
        int brokerId,
        List<Uuid> cordonedLogDirs
    ) {
        ControllerResult<BrokerHeartbeatReply> result = ctx.replicationControl.
            processBrokerHeartbeat(new BrokerHeartbeatRequestData().
                setBrokerId(brokerId).setBrokerEpoch(defaultBrokerEpoch(brokerId)).
                setCurrentMetadataOffset(1).
                setWantFence(false).setWantShutDown(false).
                setCordonedLogDirs(cordonedLogDirs), 0);
        ctx.replay(result.records());
        return result.records();
    }

    private static Set<Integer> replicaBrokers(ReplicationControlTestContext ctx, Uuid topicId, int numPartitions) {
        Set<Integer> brokers = new HashSet<>();
        for (int partitionId = 0; partitionId < numPartitions; partitionId++) {
            brokers.addAll(Replicas.toList(ctx.replicationControl.getPartition(topicId, partitionId).replicas));
        }
        return brokers;
    }

    @Test
    void testCordonedBrokersAreNotUsedForNewReplicas() {
        ReplicationControlTestContext ctx = new ReplicationControlTestContext();
        Uuid dir0 = Uuid.randomUuid();
        Uuid dir1 = Uuid.randomUuid();
        Uuid dir2a = Uuid.randomUuid();
        Uuid dir2b = Uuid.randomUuid();
        Uuid dir3 = Uuid.randomUuid();
        ctx.registerBrokersWithDirs(0, List.of(dir0), 1, List.of(dir1), 2, List.of(dir2a, dir2b), 3, List.of(dir3));
        ctx.unfenceBrokers(0, 1, 2, 3);
        Uuid stayId = ctx.createTestTopic("stay", new int[][] {new int[] {1, 2}}).topicId();
        Uuid moveId = ctx.createTestTopic("move", new int[][] {new int[] {0, 1}}).topicId();

        heartbeatWithCordonedDirs(ctx, 2, List.of(dir2a));
        assertEquals(Set.of(0, 1, 2, 3), replicaBrokers(ctx, ctx.createTestTopic("four", 8, (short) 4, NONE.code()).topicId(), 8));

        heartbeatWithCordonedDirs(ctx, 2, List.of(dir2a, dir2b));

        ctx.createTestTopic("too-many", 1, (short) 4, INVALID_REPLICATION_FACTOR.code());
        Uuid threeId = ctx.createTestTopic("three", 8, (short) 3, NONE.code()).topicId();
        assertEquals(Set.of(0, 1, 3), replicaBrokers(ctx, threeId, 8));

        ctx.createTestTopic("manual", new int[][] {new int[] {0, 2}}, INVALID_REPLICA_ASSIGNMENT.code());
        ctx.createPartitions(9, "three", new int[][] {new int[] {0, 1, 2}}, INVALID_REPLICA_ASSIGNMENT.code());
        assertEquals(8, ctx.replicationControl.getTopic(threeId).numPartitions(Long.MAX_VALUE));
        ctx.createPartitions(9, "three", new int[][] {new int[] {0, 1, 3}}, NONE.code());

        ControllerResult<List<CreatePartitionsTopicResult>> result = ctx.replicationControl.createPartitions(
            anonymousContextFor(ApiKeys.CREATE_PARTITIONS), List.of(new CreatePartitionsTopic().setName("three").setCount(20).setAssignments(null)));
        assertEquals(NONE.code(), result.response().get(0).errorCode(), result.response().get(0).errorMessage());
        ctx.replay(result.records());
        assertEquals(Set.of(0, 1, 3), replicaBrokers(ctx, threeId, 20));

        heartbeatWithCordonedDirs(ctx, 3, List.of(dir3));
        result = ctx.replicationControl.createPartitions(
            anonymousContextFor(ApiKeys.CREATE_PARTITIONS), List.of(new CreatePartitionsTopic().setName("three").setCount(30).setAssignments(null)));
        assertEquals(INVALID_REPLICATION_FACTOR.code(), result.response().get(0).errorCode());
        heartbeatWithCordonedDirs(ctx, 3, List.of());

        AlterPartitionReassignmentsRequestData request = new AlterPartitionReassignmentsRequestData().setTopics(List.of(
            new ReassignableTopic().setName("move").setPartitions(List.of(
                new ReassignablePartition().setPartitionIndex(0).setReplicas(List.of(0, 2)))),
            new ReassignableTopic().setName("stay").setPartitions(List.of(
                new ReassignablePartition().setPartitionIndex(0).setReplicas(List.of(2, 3))))));
        ControllerResult<AlterPartitionReassignmentsResponseData> alterResult =
            ctx.replicationControl.alterPartitionReassignments(request);
        assertEquals(INELIGIBLE_REPLICA.code(),
            alterResult.response().responses().get(0).partitions().get(0).errorCode());
        assertEquals(NONE.code(),
            alterResult.response().responses().get(1).partitions().get(0).errorCode(),
            alterResult.response().responses().get(1).partitions().get(0).errorMessage());
        ctx.replay(alterResult.records());
        assertEquals(List.of(1, 2, 3), Replicas.toList(ctx.replicationControl.getPartition(stayId, 0).replicas).stream().sorted().toList());
        assertEquals(List.of(0, 1), Replicas.toList(ctx.replicationControl.getPartition(moveId, 0).replicas));

        heartbeatWithCordonedDirs(ctx, 2, List.of());
        ctx.createTestTopic("all-four", 1, (short) 4, NONE.code());
    }
}

